// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;

    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(address actor, bytes32 g) public {
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(actor, 1 ether);

        // lock in a guess at the current block
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(g);
        // move to the immediately following block (== target block in both versions)
        vm.roll(block.number + 1);

        bool ok;
        vm.prank(actor);
        try c.settle() { ok = true; } catch { ok = false; }

        // Rule: settle must revert at the block right after lockInGuess,
        // because the target block is block.number+1 and settle requires
        // block.number > target.
        assertTrue(!ok);
    }
}
